const MONTH_NAMES = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const now = new Date();

// Resolves 'July', 'July 2026', '2026-07', 'last month', and '' to one month.
// Anything it cannot read becomes null, so the caller asks rather than
// silently reporting on the wrong month.
const resolveMonth = (value) => {
  const raw = String(value ?? '').trim().toLowerCase();
  const previous = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  if (!raw || raw === 'last month' || raw === 'previous month') {
    return { year: previous.getUTCFullYear(), monthIndex: previous.getUTCMonth() };
  }
  if (raw === 'this month' || raw === 'current month') {
    return { year: now.getUTCFullYear(), monthIndex: now.getUTCMonth() };
  }
  const explicit = /^(\d{4})-(\d{1,2})$/.exec(raw);
  if (explicit) {
    const monthIndex = Number(explicit[2]) - 1;
    if (monthIndex < 0 || monthIndex > 11) return null;
    return { year: Number(explicit[1]), monthIndex };
  }
  const named = /^([a-z]+)\s*(\d{4})?$/.exec(raw);
  if (named) {
    const monthIndex = MONTH_NAMES.findIndex((name) => name.startsWith(named[1]) && named[1].length >= 3);
    if (monthIndex === -1) return null;
    if (named[2]) return { year: Number(named[2]), monthIndex };
    // A bare month name means the most recent one that has already happened.
    const year = monthIndex > now.getUTCMonth() ? now.getUTCFullYear() - 1 : now.getUTCFullYear();
    return { year, monthIndex };
  }
  return null;
};

const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const AUDIENCES = ['investor', 'team', 'community'];
const rawAudience = String($json.audience ?? '').trim().toLowerCase();
const audience = AUDIENCES.includes(rawAudience) ? rawAudience : '';

let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'Starting a monthly update needs a valid conversation and request ID.' };
}

const resolved = resolveMonth($json.month);
if (!error && !resolved) {
  error = { code: 'MONTH_NOT_UNDERSTOOD', message: 'Ask the user which month they mean, and pass it as a month name or as 2026-07.' };
}

if (error) {
  return [{ json: { valid: false, shouldQueue: false, sessionId, requestId, proposedInput: { sessionId, requestId, month: String($json.month ?? ''), audience }, response: { ok: false, error } } }];
}

const start = new Date(Date.UTC(resolved.year, resolved.monthIndex, 1));
if (start.getTime() > now.getTime()) {
  return [{ json: { valid: false, shouldQueue: false, sessionId, requestId, proposedInput: { sessionId, requestId }, response: { ok: false, error: { code: 'FUTURE_MONTH', message: 'That month has not started yet.' } } } }];
}

const pad = (value) => String(value).padStart(2, '0');
const monthKey = `${resolved.year}-${pad(resolved.monthIndex + 1)}`;
const monthBucket = `${monthKey}-01`;
const MONTH_LABELS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const monthLabel = `${MONTH_LABELS[resolved.monthIndex]} ${resolved.year}`;
const isCurrentMonth = resolved.year === now.getUTCFullYear() && resolved.monthIndex === now.getUTCMonth();

return [{ json: {
  valid: true,
  sessionId,
  requestId,
  monthKey,
  monthBucket,
  monthLabel,
  audience,
  isCurrentMonth,
  runId: `mu-${monthKey}-${Date.now().toString(36)}`,
  proposedInput: { sessionId, requestId, month: monthKey, audience },
} }];

const input = $('Validate Start Input').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);

if (!input.valid) {
  return [{ json: { ...input, shouldQueue: false } }];
}

const forMonth = rows.filter((row) => String(row.monthBucket ?? '') === input.monthBucket);
const running = forMonth.find((row) => ['queued', 'running'].includes(String(row.status ?? '')));

// Two runs over the same month would read the same mail twice and bill for
// it twice, so an in-flight run is reported rather than duplicated.
if (running) {
  return [{ json: { ...input, shouldQueue: false, runId: running.runId, response: {
    ok: true,
    status: running.status,
    runId: running.runId,
    monthLabel: input.monthLabel,
    message: `I am already working through ${input.monthLabel}. Ask me for it again in a few minutes.`,
  } } }];
}

const finished = forMonth
  .filter((row) => ['completed', 'partial'].includes(String(row.status ?? '')))
  .sort((a, b) => String(b.startedAt ?? '').localeCompare(String(a.startedAt ?? '')))[0];

return [{ json: {
  ...input,
  shouldQueue: true,
  previousRunId: finished?.runId ?? '',
  replacedEarlier: Boolean(finished),
} }];

const input = $('Decide Run').first().json;

return [{ json: { ...input, response: {
  ok: true,
  status: 'queued',
  runId: input.runId,
  monthLabel: input.monthLabel,
  audience: input.audience || 'the audience saved on the profile',
  message: [
    `I am reading ${input.monthLabel} now. It takes a few minutes: I list the month's mail, filter it against your company profile, read the threads that survive, and then write the update.`,
    input.isCurrentMonth ? 'That month is not finished yet, so this covers what has happened so far.' : '',
    input.replacedEarlier ? 'There was already an update for that month; this run writes a fresh one.' : '',
    'Ask me for it again in a few minutes and I will read it back.',
  ].filter(Boolean).join(' '),
} } }];

const input = $('Decide Run').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'start_monthly_update',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
const CONNECT_PATH = '/api/gmail/connect';

let state = 'unknown';
let message = '';

if (status !== 200) {
  state = 'unknown';
  message = 'I could not reach the part of this app that holds the Gmail connection. If you have just restarted, give it a moment and ask again.';
} else if (body.configured !== true) {
  state = 'not_configured';
  message = 'This computer has no Google sign-in set up yet. That is a one-off job: create a Google Cloud OAuth client, then put its ID and secret in the .env file and restart. docs/MONTHLY_UPDATE.md walks through it.';
} else if (body.connected !== true) {
  state = 'not_connected';
  message = 'Gmail is not connected yet. One click does it, and Google will ask you to allow read-only access to your email.';
} else if (String(body.lastError ?? '') !== '') {
  state = 'needs_reauth';
  message = 'Gmail was connected but Google has stopped renewing it. Connecting again fixes it. If this is about a week after you set it up, the cause is a Google consent screen still in Testing rather than published.';
} else {
  state = 'connected';
  message = body.emailAddress ? `Gmail is connected as ${body.emailAddress}.` : 'Gmail is connected.';
}

return [{ json: {
  connected: state === 'connected',
  state,
  message,
  emailAddress: String(body.emailAddress ?? ''),
  connectUrl: CONNECT_PATH,
  scope: 'https://www.googleapis.com/auth/gmail.readonly',
  // The chat turns this exact path into a button. Any other wording renders as
  // plain text and the learner has nothing to click.
  linkInstruction: `Include the exact text ${CONNECT_PATH} in your reply. The chat turns it into a Connect Gmail button. Do not rewrite it, wrap it in markdown, or describe it instead.`,
} }];

const input = $('Decide Run').first().json;
const probe = $('Read Gmail Probe').first().json;

// Refusing here costs two seconds. Queueing anyway would spend several
// minutes and a couple of dollars before failing at the first Gmail call.
const NEXT = {
  not_connected: 'Do not start the run. Tell the user you need to read their email first, and include the exact text /api/gmail/connect in your reply so the chat shows them a Connect Gmail button. Say Google will ask them to allow read-only access. Once they connect, the update starts on its own.',
  needs_reauth: 'Do not start the run. Tell the user the connection has lapsed and include the exact text /api/gmail/connect in your reply so they can reconnect in one click.',
  not_configured: 'Do not start the run. This computer has no Google sign-in configured, which is a one-off setup job in the .env file. Point the user at docs/MONTHLY_UPDATE.md rather than improvising the steps, and do not offer a connect link: it cannot work yet.',
  unknown: 'Do not start the run. Say the connection could not be checked right now and offer to try again in a moment.',
};

return [{ json: { ...input, response: {
  ok: false,
  error: {
    code: probe.state === 'needs_reauth' ? 'GMAIL_NEEDS_RECONNECT' : 'GMAIL_NOT_CONNECTED',
    message: probe.message,
  },
  state: probe.state,
  connectUrl: probe.connectUrl,
  linkInstruction: probe.linkInstruction,
  requiredScope: probe.scope,
  nextStep: NEXT[probe.state] ?? NEXT.unknown,
} } }];
